  for (const [name, id] of seen) if (id !== null) only.set(name, id);
  return only;
}

import type { Identity, Line, Occurrence, Review } from "./dagger.ts";

/* Turning one side of a definition into the lines a diff can be drawn from, and picking
 * out the names in a review that a highlighter is allowed to point at.
 */

import type { Identity, Line, Occurrence, Review } from "./dagger.ts";

/* Turning one side of a definition into the lines a diff can be drawn from, and picking
 * out the names in a review that a highlighter is allowed to point at.
 */

type.text:
export type Review = { definitions: { [key in Identity]: Definition }, 
/**
 * What to read, in order. Whatever a step names is worth reading; everything else in
 * `definitions` is here to be drawn around it.
 */
reading: Array<Step>, edges: Array<Edge>, groups: Array<Group>, 
/**
 * What a reader calls the grouping: "package", "crate".
 */
grouping: string | null, 
/**
 * How far this reading was told to follow a change outward.
 */
ripples: number, cost: Cost, warnings: Array<Warning>, };

before.type_from_compiler:
type Review = {
    definitions: { [key in Identity]: Definition; };
    reading: Array<Step>;
    edges: Array<Edge>;
    groups: Array<Group>;
    grouping: string | null;
    ripples: number;
    cost: Cost;
    warnings: Array<Warning>;
}

